// CallerUnknown is the caller of a request that was rejected before an identity
// could be established. Identity is always derived server-side (FR-011, T012);
// a request never names its own caller.
const CallerUnknown = "unknown"

// Record is one audit entry. Every field is a plain string by construction —
// there is deliberately no map, no slice, no any, and no attribute passthrough,
// so there is nowhere for a prompt, a pane capture, a token, or a request body
// to be attached. Adding such a field is the thing FR-042 forbids, and
// audit_test.go fails if one appears.
type Record struct {
	// Action is required.
	Action Action

	// Caller is the server-derived identity. Empty becomes CallerUnknown, so
	// the field is present on every record including a rejection.
	Caller string

	// SessionID is the 32-hex session ID, omitted when the action is not about
	// one particular session.
	SessionID string

	// Decision is required and must be Allow or Deny.
	Decision Decision

	// Reason explains a decision for the operator reading the trail. It is
	// server-authored and stays server-side: the client always sees a uniform
	// message (FR-011). It must never be built from caller-supplied text, a
	// prompt, pane output, a token, or the shared secret (FR-042, FR-043).
	Reason string

	// Remote is the peer address, omitted for actions with no request behind
	// them such as the reaper and startup adoption.
	Remote string
}

// Logger writes records to one sink. Safe for concurrent use: slog's handler
// serialises writes, which is what lets every request path share one Logger.
type Logger struct {
	handler slog.Handler
	now     func() time.Time
}

// New writes the trail to standard output, which is the only destination the
// daemon has (FR-041). It is the form cmd/crswd needs.
func New() *Logger { return NewTo(os.Stdout, time.Now) }

// NewTo is New with the sink and the clock injected, so tests can read back
// exactly what was written and assert on a fixed timestamp. Same seam as
// config.LoadFrom and tmuxctl's SetNow.
func NewTo(w io.Writer, now func() time.Time) *Logger {
	if w == nil {
		w = os.Stdout
	}
	if now == nil {
		now = time.Now
	}
	return &Logger{handler: newHandler(w), now: now}
}

// second, quieter way of reporting the one thing Principle VI does not let this
// daemon report quietly.
type destroyResponse struct {
	ID        string `json:"id"`
	Destroyed bool   `json:"destroyed"`
}

// promptRequest is the fixed shape POST /sessions/{id}/prompt accepts: one
// field, which is the text to deliver (contracts/http-api.md).
//
// There is deliberately no session field. Which session a prompt is for is
// settled by the path and the credential presented for it, both of which layer 3
// has already checked; a body that could name a session would be a second answer
// to that question, free to disagree with the first.
type promptRequest struct {
	// Text is data, not a command. It is length-bounded by CRSW_MAX_BODY_BYTES
	// and required to be non-empty, and that is the whole of its validation
	// (FR-030): it is delivered byte-for-byte, so anything this handler
	// "sanitised" would be a prompt the caller did not send.
	Text string `json:"text"`
}

// promptResponse is the contract's 202 body. It carries the daemon's own ID for
// the session and no echo of the text — which is not merely unnecessary but
// forbidden: prompt text is secret under docs/security.md §3, and a response
// that repeats it is one more place it can be logged by whatever reads it.
//
// ParkedOn and SuspiciousDialog are additive (PR #150 follow-up). `delivered`
// keeps meaning exactly what it always has — the keystrokes reached the pane —
// because that claim was never false; what was false is a caller reading it as
// "reached a prompt". Both new fields default to their zero value and are
// omitted then, so a caller checking only `delivered` sees byte-for-byte the
// response it always has.
type promptResponse struct {
	ID        string `json:"id"`
	Delivered bool   `json:"delivered"`

	// ParkedOn names the internal/session/dialog.go signature the pane matched
	// at the moment this prompt was delivered — set only then. It is a fixed
	// registry name (`"workspace-trust"`, `"rc-menu"`), never pane text: naming

// credential issued for it, and has stamped that record's ID on the audit
// record — so this handler neither reads the path nor sets a session ID, and
// there is no version of it that could act on a session it was not given.
//
// Delivery itself belongs to internal/session, which is the only thing here that
// can cause execution on the host. What is left is the HTTP half: read the one
// field, hand it over unaltered, and answer.
//
// The dialog check reads the pane before Prompt runs, deliberately. It asks
// what the keystroke is about to land in rather than what the pane holds
// afterwards, because the keystroke itself may dismiss or change a menu —
// checking after would be asking the question once the answer had moved.
func (s *Server) promptSession(w http.ResponseWriter, r *http.Request) {
	resolved, ok := SessionFrom(r.Context())
	if !ok {
		s.failInternal(w, r, errPromptNoSession)
		return
	}

	req, ok := decode[promptRequest](s, w, r)
	if !ok {
		return
	}

	// Guarded on the same emptiness Manager.Prompt itself refuses on
	// (ErrEmptyPrompt), so that a body this route was always going to reject
	// still costs the host nothing at all — not even a read. Duplicating the
	// bare emptiness check here is not duplicating the rule: Manager.Prompt
	// still owns ErrEmptyPrompt and every other reason a prompt can be
	// refused, and refusePrompt below still asks it rather than assuming.
	var parkedOn string
	var suspicious bool
	if req.Text != "" {
		parkedOn, suspicious = s.paneDialogState(r.Context(), resolved)
	}

	if err := s.sessions.Prompt(r.Context(), resolved, req.Text); err != nil {
		s.refusePrompt(w, r, err)
		return
	}

	// 202, not 200: what is confirmed is that the keystrokes reached the pane,
	// which is not the same claim as Claude having read them, and the contract
	// spells that difference as "accepted for delivery". ParkedOn and
	// SuspiciousDialog narrow that further still: they say the keystrokes
	// reached a dialog rather than a prompt, when the pane check above found
	// one to say it about.
	s.writeJSON(w, r, http.StatusAccepted, promptResponse{
		ID:               resolved.ID,
		Delivered:        true,
		ParkedOn:         parkedOn,
		SuspiciousDialog: suspicious,
	})
}

// paneDialogState best-effort-checks whether resolved's pane is presently
// sitting on a known TUI dialog (internal/session/dialog.go), for a prompt
// about to be delivered into it.
//
// A capture that fails degrades to this route's answer before this check
// existed — an ordinary delivery, with neither field set — because a
// heuristic's own precondition failing is not a reason to treat an otherwise
// normal prompt as suspicious, and is not a reason to refuse it either: the
// check is additive information, never a gate (see the requirement this
// implements — the task named the readiness-signal, refuse-the-prompt version
// of this feature as the harder half deliberately left undone). A successful
// read can only ever upgrade the answer, never downgrade one an operator would
// otherwise have gotten.
func (s *Server) paneDialogState(ctx context.Context, resolved session.Session) (parkedOn string, suspicious bool) {
	capture, err := s.sessions.Output(ctx, resolved)
	if err != nil {
		return "", false
	}
	name, dialog := session.DetectDialogFor(s.sessions.SpecOf(resolved).Name, capture.Text)
	if !dialog {
		return "", false
	}
	return name, name == ""
}

// refusePrompt maps a Prompt failure onto the answer the contract gives it.
//
// An empty text is the one thing the caller can fix, and it is a 400 with the
// same uniform body every other refused body gets. Everything else is a 500 with
// no detail — including a dead session, which the resolver already refuses as a
// 404 and which reaching here would mean a record went terminal between two
// layers of the same request. That is a fact about the host's state, and telling
// a caller which of tmux's failures it hit would be an oracle about a machine it
// cannot otherwise see.
func (s *Server) refusePrompt(w http.ResponseWriter, r *http.Request, err error) {
	if errors.Is(err, session.ErrEmptyPrompt) {
		s.rejectBadRequest(w, r, session.ErrEmptyPrompt)
		return
	}
	s.failInternal(w, r, errPromptUndelivered)
}

// sessionOutput is GET /sessions/{id}/output: hand back what the session's pane
// currently holds, as text (contracts/http-api.md).
//
// The session comes from the context and nowhere else, exactly as it does for a
// prompt, and the capture itself belongs to internal/session — the stripper runs
// where output leaves that package, so what arrives here is already the bytes
// that may go out.
//
// There is one failure answer and it is a 500 with no detail. A pane that could
// not be read is a fact about the host: whether tmux is missing, whether the
// server died, or whether the window vanished under a record that still resolves
// are distinctions an operator reads in the trail, and telling them apart for a
// caller would be an oracle about a machine it cannot otherwise see.

// there is no second lookup here to disagree with the first, and no path by
// which a caller's spelling of an ID could name a window.
//
// Two commands, in this order and no other. Paste writes the bytes to a tmux
// buffer over stdin, so the payload never becomes part of a command line
// (FR-029) — research D4 is the reason this is not send-keys -l, which drops a
// trailing unescaped ";" from caller text before -l ever applies. The Return
// that follows is a daemon-authored key constant and travels the way the Claude
// start command does. Nothing escapes, quotes, or inspects the text: it is data.
//
// A failure leaves the text where it fell. The buffer paste-buffer -d would have
// deleted may survive a failed submit, which is prompt text sitting in a named
// tmux buffer another client could read — the caller is told the prompt did not
// land, and the buffer is overwritten by the next prompt to the same session.
func (m *Manager) Prompt(ctx context.Context, s Session, text string) error {
	// Unreachable behind the resolver, and refused rather than trusted: an empty
	// ID would build the bare prefix as a target, and a dead session's window is
	// already gone. Both fail closed here so that a future caller reaching this
	// method with a hand-made record cannot type into whatever that names.
	if s.ID == "" {
		return fmt.Errorf("prompt session: %w", ErrSessionNotFound)
	}
	if s.State == StateDead {
		return fmt.Errorf("prompt session %s: %w", s.ID, ErrSessionDead)
	}
	if text == "" {
		return fmt.Errorf("prompt session %s: %w", s.ID, ErrEmptyPrompt)
	}

	unlock := m.lockSession(s.ID)
	defer unlock()

	name := s.TmuxName()

	// The error deliberately names the session and nothing else. Prompt text is
	// secret under docs/security.md §3, so it may not travel back to a caller in
	// an error string any more than it may reach the trail (FR-042).
	if err := m.paste(ctx, s, []byte(text)); err != nil {
		return fmt.Errorf("paste the prompt into session %s: %w", s.ID, err)
	}
	if err := m.tmux.SendKeys(ctx, name, enterKey); err != nil {
		return fmt.Errorf("submit the prompt in session %s: %w", s.ID, err)
	}
	return nil
}

// specOf is the harness facts for a session, derived from its configured start
// command each time (research D1). A name the operator has since removed reads
// as Other, whose spec asks for nothing special.
func (m *Manager) specOf(s Session) harness.Spec {
	// An adopted session that recorded no start-command name has no known
	// harness: labelling it with whatever the default is now would be a guess.
	if s.Adopted && s.StartCommand == "" {
		return harness.For(harness.Other)
	}
	name := s.StartCommand
	if name == "" {
		name = config.DefaultStartCommandName
	}
	cmd, err := m.resolveStartCommand(name)
	if err != nil {
		return harness.For(harness.Other)
	}
	return harness.For(harness.Of(cmd))
}

// SpecOf is specOf for callers outside the package.
func (m *Manager) SpecOf(s Session) harness.Spec { return m.specOf(s) }

// paste delivers a payload the way the session's harness submits it: Codex
// swallows the Enter after a plain paste (research M3), so it gets a bracketed
// one. It serves Prompt and Compact only. Type is bracketed for every harness
// and must not route through here, because Claude's BracketedPaste is false.
func (m *Manager) paste(ctx context.Context, s Session, payload []byte) error {
	if m.specOf(s).BracketedPaste {
		return m.tmux.PasteBracketed(ctx, s.TmuxName(), payload)
	}
	return m.tmux.Paste(ctx, s.TmuxName(), payload)
}

// Compact asks a session to compact itself, by delivering Claude Code's own
// /compact into it (FR-016).
//
// What it may claim is the whole of its shape. The daemon cannot see what the
// assistant is carrying, so nothing here observes a compaction: a nil error
// means the bytes reached the pane and means nothing else (FR-016a). A caller
// turning that into "compacted" would be asserting something no part of this
