const fakeAliveCommand = "claude"

// livenessOf is the comparison the real List has tmux make, made here instead so
// the fake models the round trip rather than only its first half. A fake that
// always answered "running" would let every revival test pass against a daemon
// that never revives anything.
//
// The binary may be a set of names joined by "|", which tmux reads as regex
// alternation. An empty element is skipped so it can never match an empty pane.
func livenessOf(binary, paneCommand string) Liveness {
	if binary == "" {
		return LivenessUnknown
	}
	for _, name := range strings.Split(binary, "|") {
		if name != "" && name == paneCommand {
			return LivenessRunning
		}
	}
	return LivenessStopped
}

// Fake is an in-memory Controller for every other package's tests, so no unit
// test needs a real tmux binary. It is safe for concurrent use — the reaper,
// destroy, and the session cap all race against each other by design.
//
// Construct it with NewFake. The knobs (Seed, Vanish, SurviveKill, FailOp,
// SetPane, SetNow) reproduce the states that only a broken or restarted host
// would otherwise produce.
type Fake struct {
	mu        sync.Mutex
	calls     []Call
	sessions  map[string]*fakeSession
	surviving map[string]bool
	fail      map[Op]error
	now       func() time.Time
	buffers   uint64
}

// nextBuffer is the fake's stand-in for the random buffer name Exec draws. The
// caller holds f.mu.
func (f *Fake) nextBuffer() string {
	f.buffers++
	return FakeBufferName(f.buffers)
}

type fakeSession struct {
	workDir string
	created time.Time

	// paneCommand is what List reports as #{pane_current_command}. It defaults
	// to fakeAliveCommand because a seeded session models a *healthy* one, which
	// is what every test that is not about death needs; SetPaneCommand is how a
	// test that is about death says so.
	paneCommand string
	options     map[string]string
	pane        string
	history     string

	// panePID is what PanePID reports. Zero is unset, which the fake answers as
	// tmux printing something unreadable, so a test that walks /proc says which
	// pid it means rather than inheriting one.
===
	return out, stats, nil
}

// claimRestart takes the single-restart claim for a session, and reports whether
// it got it (spec 013, FR-012).
//
// Two things restart a session's process: the supervisor reviving one that died,
// and an operator continuing a different conversation. Both interrupt the pane
// and type a start command into it, so exactly one may be doing that at a time —
// the alternative is two Claude processes in one shell, which is a session with
// two of everything and an operator watching whichever one draws last.
//
// The map is created lazily so a Manager built by a struct literal, or by a test
// that predates this field, is still a working Manager.
func (m *Manager) claimRestart(id string) bool {
	m.restartingMu.Lock()
	defer m.restartingMu.Unlock()

	if m.restarting == nil {
		m.restarting = make(map[string]bool)
	}
	if m.restarting[id] {
		return false
	}
	m.restarting[id] = true
	return true
}

func (m *Manager) releaseRestart(id string) {
	m.restartingMu.Lock()
	defer m.restartingMu.Unlock()
	delete(m.restarting, id)
}

